	('4b98e29d-923a-4d0c-8638-bbf4831ca6d4', 'Positionnement - Compétences langagières (écrit) + compétences transversales', 'ct_et_litteratie', '1 heure', '2023-04-03 16:00:38', '2025-04-24 09:33:26', 'Ce parcours permet, à la fois :


